challenge.solution:
.skills ul { display: flex; gap: 1rem; list-style: none; padding: 0; }
.skills li { flex: 1; padding: .75rem; background: #fff7ed; border-radius: .5rem; }
@media (max-width: 30rem) { .skills ul { flex-direction: column; } }

exercise.solution:
.card { box-sizing: border-box; width: 100%; max-width: 42rem; margin: 2rem auto; padding: 1.5rem; border: 1px solid #ddd; border-radius: 1rem; }
.card-links { display: flex; gap: .75rem; justify-content: flex-end; }
@media (max-width: 30rem) { .card-links { flex-direction: column; } }

.profile-panel { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; }
.profile-panel > * { min-width: 0; }
@media (max-width: 37.5rem) { .profile-panel { grid-template-columns: 1fr; } }
